#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>
#include <noarr/structures/interop/traverser_iter.hpp> // for traverser range-based for / parallel splitting

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

namespace {

// -----------------------------------------------------------------------------
// Layout / tuning
// -----------------------------------------------------------------------------

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto t_vec = noarr::vector<'t'>();

// Chunk size for OpenMP over traverser ranges.
// This is a single knob you can tune for different core / cache configurations.
constexpr int OMP_CHUNK_SIZE = 8;

struct tuning {
	// 2D fields: i x j, with j the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(field_layout, j_vec ^ i_vec);
	// 1D fictitious array over time
	DEFINE_PROTO_STRUCT(fict_layout, t_vec);
} tuning;

// -----------------------------------------------------------------------------
// Small helper: parallel traversal over outermost dimension using OpenMP
// -----------------------------------------------------------------------------

/*
 * Split a traverser along its topmost dimension and let OpenMP distribute
 * the resulting independent sub-traversers across threads. Each sub-traverser
 * then uses `for_each` to walk its part of the domain.
 *
 * - If compiled without -fopenmp, the pragma is ignored and execution stays
 *   sequential, still using the same Noarr traversal semantics.
 * - The loop nest that actually touches elements is always a Noarr traverser
 *   (`sub_trav.for_each(f)`), satisfying the "loops via traverser" constraint.
 */
template<typename Trav, typename Fun>
inline void parallel_trav_for_each(const Trav &trav, const Fun &f) {
	#pragma omp parallel for schedule(static, OMP_CHUNK_SIZE)
	for (auto sub_trav : trav) { // traverser iterator: splits along outermost dim
		sub_trav.for_each(f);
	}
}

// -----------------------------------------------------------------------------
// Array initialization
// -----------------------------------------------------------------------------

void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Initialize fict[t] = t
	parallel_trav_for_each(traverser(fict), [=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = static_cast<num_t>(t);
	});

	// Dimensions
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Precompute reciprocals once to avoid repeated divisions in the inner loops.
	const num_t inv_nx = static_cast<num_t>(1) / static_cast<num_t>(nx);
	const num_t inv_ny = static_cast<num_t>(1) / static_cast<num_t>(ny);

	// Initialize ex, ey, hz
	parallel_trav_for_each(traverser(ex, ey, hz), [=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const num_t i_val = static_cast<num_t>(i);

		// Preserve original semantics: form (j + k) in index space, then cast.
		const num_t j1 = static_cast<num_t>(j + 1u);
		const num_t j2 = static_cast<num_t>(j + 2u);
		const num_t j3 = static_cast<num_t>(j + 3u);

		ex[state] = i_val * j1 * inv_nx;
		ey[state] = i_val * j2 * inv_ny;
		hz[state] = i_val * j3 * inv_nx;
	});
}

// -----------------------------------------------------------------------------
// Main computational kernel
// -----------------------------------------------------------------------------

[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Hoist scalar coefficients out of the loops.
	const num_t half = SCALAR_VAL(0.5);
	const num_t c07  = SCALAR_VAL(0.7);

	// BLAS-like params in original:
	// Time-stepping FDTD on a 2D grid

#pragma scop
	// Outer time loop over t
	traverser(fict, ex, ey, hz).template for_dims<'t'>([=](auto trav_t) {
		// State with only the current time index t fixed.
		auto t_state = trav_t.state();

		// ---------------------------------------------------------------------
		// 1) ey[0][j] = fict[t] for all j
		//    Domain: i = 0, j = 0..ny-1
		// ---------------------------------------------------------------------
		auto trav_ey_bc = trav_t.order(noarr::fix<'i'>(0));

		parallel_trav_for_each(trav_ey_bc, [=](auto state) {
			// state: i = 0, all j for this t
			ey[state] = fict[t_state];
		});

		// ---------------------------------------------------------------------
		// 2) ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j])
		//    for i = 1..nx-1, j = 0..ny-1
		// ---------------------------------------------------------------------
		auto trav_ey = trav_t.order(noarr::slice<'i'>(1, nx - 1));

		parallel_trav_for_each(trav_ey, [=](auto state) {
			// state: i in [1, nx-1], j in [0, ny-1]
			auto state_im1j = state - noarr::idx<'i'>(1);

			const num_t hz_ij   = hz[state];
			const num_t hz_im1j = hz[state_im1j];

			// Update ey in-place; each (i,j) is independent in this loop.
			ey[state] = ey[state] - half * (hz_ij - hz_im1j);
		});

		// ---------------------------------------------------------------------
		// 3) ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1])
		//    for i = 0..nx-1, j = 1..ny-1
		// ---------------------------------------------------------------------
		auto trav_ex = trav_t.order(noarr::slice<'j'>(1, ny - 1));

		parallel_trav_for_each(trav_ex, [=](auto state) {
			// state: i in [0, nx-1], j in [1, ny-1]
			auto state_ijm1 = state - noarr::idx<'j'>(1);

			const num_t hz_ij   = hz[state];
			const num_t hz_ijm1 = hz[state_ijm1];

			ex[state] = ex[state] - half * (hz_ij - hz_ijm1);
		});

		// ---------------------------------------------------------------------
		// 4) hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j]
		//                                 + ey[i+1][j] - ey[i][j])
		//    for i = 0..nx-2, j = 0..ny-2
		// ---------------------------------------------------------------------
		auto trav_hz = trav_t.order(
			noarr::slice<'i'>(0, nx - 1) ^
			noarr::slice<'j'>(0, ny - 1)
		);

		parallel_trav_for_each(trav_hz, [=](auto state) {
			// state: i in [0, nx-2], j in [0, ny-2]
			auto state_i_jp1 = state + noarr::idx<'j'>(1);
			auto state_ip1_j = state + noarr::idx<'i'>(1);

			const num_t hz_ij     = hz[state];

			const num_t ex_ij     = ex[state];
			const num_t ex_i_jp1  = ex[state_i_jp1];

			const num_t ey_ij     = ey[state];
			const num_t ey_ip1_j  = ey[state_ip1_j];

			const num_t diff_ex = ex_i_jp1 - ex_ij;
			const num_t diff_ey = ey_ip1_j - ey_ij;

			hz[state] = hz_ij - c07 * (diff_ex + diff_ey);
		});
	});
#pragma endscop
}

} // namespace

// -----------------------------------------------------------------------------
// Boilerplate (unchanged): problem setup, timing, and output
// -----------------------------------------------------------------------------

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t tmax = TMAX;
	std::size_t nx = NX;
	std::size_t ny = NY;

	// Set lengths for spatial and temporal dimensions
	auto set_space = noarr::set_length<'i'>(nx) ^ noarr::set_length<'j'>(ny);
	auto set_time  = noarr::set_length<'t'>(tmax);

	// Allocate bags
	auto ex = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto ey = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto hz = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto fict = noarr::bag(noarr::scalar<num_t>() ^ tuning.fict_layout ^ set_time);

	// Initialize arrays
	init_array(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// Start timer
	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_fdtd_2d(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// Stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print results (if requested, mimicking PolyBench's conditional printing)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);

		// Hoist 'i' so each row is contiguous in the serialized output
		noarr::serialize_data(std::cerr, ex.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, ey.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, hz.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print elapsed time (seconds)
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
