// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// 2D fields: i x j, with j the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(field_layout, j_vec ^ i_vec);
	// 1D fictitious array over time
	DEFINE_PROTO_STRUCT(fict_layout, t_vec);

	// Simple compile‑time tuning knob: number of rows per spatial block.
	// This is used only for traversal order (no change in data layout).
	// Must be > 0; can be retuned for different machines.
	static constexpr std::size_t tile_i = 32;
} tuning;

// Array initialization
void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Initialize fict[t] = t
	traverser(fict).for_each([=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = (num_t)t;
	});

	// Dimensions
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Precompute reciprocals once instead of doing a division per element
	const num_t inv_nx = num_t(1) / num_t(nx);
	const num_t inv_ny = num_t(1) / num_t(ny);

	// Initialize ex, ey, hz
	traverser(ex, ey, hz).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const num_t fi = num_t(i);
		const num_t fjp1 = num_t(j + 1);
		const num_t fjp2 = num_t(j + 2);
		const num_t fjp3 = num_t(j + 3);

		ex[state] = (fi * fjp1) * inv_nx;
		ey[state] = (fi * fjp2) * inv_ny;
		hz[state] = (fi * fjp3) * inv_nx;
	});
}

// Main computational kernel
//
// Optimizations compared to the baseline version:
//  - Precompute constants 0.5 and 0.7 as num_t.
//  - Use local temporaries inside the stencil updates to reduce repeated
//    bag lookups and arithmetic.
//  - Introduce a tunable blocking in the 'i' (row) dimension using
//    noarr::into_blocks_dynamic + noarr::hoist to improve cache locality.
//  - Parallelize each spatial sweep for a fixed time step over the
//    'i'-blocks using OpenMP and traverser iterators.  This preserves the
//    dependence across time steps while exploiting spatial parallelism.
//
// NOTE: OpenMP pragmas are optional – if compiled without -fopenmp they
//       are ignored by the compiler and the code remains correct.
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	const num_t half          = SCALAR_VAL(0.5);
	const num_t seven_tenths  = SCALAR_VAL(0.7);

	// Proto-structure for blocking in the 'i' (row) dimension.
	// - into_blocks_dynamic<'i','I','i','r'>(...) splits 'i' into:
	//     'I' ... block index (outer)
	//     'i' ... index within block
	//     'r' ... presence flag (used to safely handle incomplete blocks)
	// - hoist<'I'>() makes 'I' the outermost traversed dimension
	//
	// When used via traverser(...).order(block_i_proto), the *states*
	// seen in the lambdas remain in the original coordinates ('i','j'),
	// but the traversal order is organized by blocks of rows.
	constexpr auto block_i_proto =
		noarr::into_blocks_dynamic<'i', 'I', 'i', 'r'>(noarr::lit<tuning::tile_i>)
		^ noarr::hoist<'I'>();

#pragma scop
	// Outer time loop over t. We keep the temporal dependence by
	// traversing 't' sequentially and only parallelizing the spatial work
	// inside each time step.
	traverser(fict, ex, ey, hz).template for_dims<'t'>([=](auto trav_t) {
		// State with only the current time index (used to read fict[t])
		auto t_state = trav_t.state();

		// -----------------------------------------------------------------
		// ey[0][j] = fict[t] for all j
		// -----------------------------------------------------------------
		trav_t
			.order(noarr::fix<'i'>(0))
			.for_each([&](auto state) {
				// state has i = 0, all j; t is taken from t_state
				ey[state] = fict[t_state];
			});

		// -----------------------------------------------------------------
		// ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j])
		// for i = 1..nx-1, j = 0..ny-1
		//
		// We block the 'i' dimension to improve cache locality and then
		// parallelize over the resulting row blocks.
		// -----------------------------------------------------------------
		{
			auto trav_ey = trav_t.order(
				noarr::slice<'i'>(1, nx - 1) // i in [1, nx-1]
				^ block_i_proto              // blocked rows, hoisted 'I'
			);

			// Parallel over 'I' (row blocks). Each inner traverser
			// operates on a disjoint set of rows, so there are no
			// write-write races.
#pragma omp parallel for
			for (auto trav_block : trav_ey) {
				trav_block.for_each([&](auto state) {
					// state: i in [1, nx-1], j in [0, ny-1]
					auto state_im1j = state - idx<'i'>(1);

					const num_t hz_curr = hz[state];
					const num_t hz_prev = hz[state_im1j];
					const num_t ey_val  = ey[state];

					ey[state] = ey_val - half * (hz_curr - hz_prev);
				});
			}
		}

		// -----------------------------------------------------------------
		// ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1])
		// for i = 0..nx-1, j = 1..ny-1
		//
		// Again, block in 'i' and parallelize over row blocks. Within a
		// row, the update depends only on hz[i][j] and hz[i][j-1], so
		// there are no dependences across rows.
		// -----------------------------------------------------------------
		{
			auto trav_ex = trav_t.order(
				noarr::slice<'j'>(1, ny - 1) // j in [1, ny-1]
				^ block_i_proto              // blocked rows, hoisted 'I'
			);

#pragma omp parallel for
			for (auto trav_block : trav_ex) {
				trav_block.for_each([&](auto state) {
					// state: i in [0, nx-1], j in [1, ny-1]
					auto state_ijm1 = state - idx<'j'>(1);

					const num_t hz_curr = hz[state];
					const num_t hz_left = hz[state_ijm1];
					const num_t ex_val  = ex[state];

					ex[state] = ex_val - half * (hz_curr - hz_left);
				});
			}
		}

		// -----------------------------------------------------------------
		// hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j]
		//                             + ey[i+1][j] - ey[i][j])
		// for i = 0..nx-2, j = 0..ny-2
		//
		// This uses ex and ey updated in the current time step, but only
		// reads them, so we can safely parallelize over row blocks.
		// -----------------------------------------------------------------
		{
			auto trav_hz = trav_t.order(
				// i in [0, nx-2], j in [0, ny-2]
				noarr::slice<'i'>(0, nx - 1)
				^ noarr::slice<'j'>(0, ny - 1)
				^ block_i_proto // blocked rows, hoisted 'I'
			);

#pragma omp parallel for
			for (auto trav_block : trav_hz) {
				trav_block.for_each([&](auto state) {
					// state: i in [0, nx-2], j in [0, ny-2]
					auto state_i_jp1 = state + idx<'j'>(1);
					auto state_ip1_j = state + idx<'i'>(1);

					const num_t hz_val    = hz[state];
					const num_t ex_right  = ex[state_i_jp1];
					const num_t ex_center = ex[state];
					const num_t ey_down   = ey[state_ip1_j];
					const num_t ey_center = ey[state];

					hz[state] = hz_val
					            - seven_tenths *
					              ((ex_right - ex_center) +
					               (ey_down  - ey_center));
				});
			}
		}
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t tmax = TMAX;
	std::size_t nx = NX;
	std::size_t ny = NY;

	// Set lengths for spatial and temporal dimensions
	auto set_space = noarr::set_length<'i'>(nx) ^ noarr::set_length<'j'>(ny);
