/**
 * Small helper to parallelize a traverser over a chosen
 * dimension using OpenMP, while still expressing the inner
 * loop nest via Noarr traversers.
 *
 * Dim  - dimension along which we split work (e.g. 'i')
 * Trav - traverser type
 * Func - element functor: (state) -> void
 *
 * The helper:
 *   - builds a 1D range over Dim (trav.range<Dim>())
 *   - parallelizes the outer loop over that range
 *   - calls inner_trav.for_each(func) to handle remaining dims
 *
 * This respects the guideline that loop nests are expressed
 * via Noarr traversers; OpenMP only distributes the outer
 * iterations (sub-traversers).
 */
template<auto Dim, class Trav, class Func>
inline void omp_trav_for_each_dim(const Trav &trav, const Func &func) {
	auto range = trav.template range<Dim>(); // range over Dim
	const std::size_t n = range.size();

#pragma omp parallel for schedule(static)
	for (std::size_t idx = 0; idx < n; ++idx) {
		auto inner_trav = range[idx]; // traverser with Dim fixed
		inner_trav.for_each(func);
	}
}

