void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	const auto nx = ex | get_length<'i'>();
	const auto ny = ex | get_length<'j'>();

	// Hoisted scalar constants to avoid recomputing inside inner loops
	const num_t half = SCALAR_VAL(0.5);
	const num_t c07  = SCALAR_VAL(0.7);

#pragma scop
	// Outer time loop over t
	traverser(fict, ex, ey, hz).template for_dims<'t'>([=](auto trav_t) {
		// trav_t has 't' fixed; remaining dims: 'i', 'j'

		// Load fict[t] once per time step (all j in row i=0 use the same value)
		const num_t fict_t = fict[trav_t];

