		// 1) ey[0][j] = fict[t]   for all j
		// ------------------------------------------------------------------
		// Restrict to i = 0; remaining dimension is 'j' (contiguous)
		auto trav_ey_boundary = trav_t.order(fix<'i'>(0));
		trav_ey_boundary.for_each([=](auto state) {
			// state has i = 0, j varying; t fixed by trav_t
			ey[state] = fict_t;
		});

		// ------------------------------------------------------------------
		// 2) ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j])
		//    for i = 1..nx-1, j = 0..ny-1
		// ------------------------------------------------------------------
		// Restrict i to [1, nx-1]; dims: i (outer), j (inner)
		auto trav_ey_interior = trav_t.order(slice<'i'>(1, nx - 1));

