		// rows and iterates columns 'j' via for_each.
		omp_trav_for_each_dim<'i'>(trav_ey_interior, [=](auto state) {
			// state: i in [1, nx-1], j in [0, ny-1], t fixed
			auto state_im1j = state - idx<'i'>(1);

			const num_t hz_c   = hz[state];
			const num_t hz_im1 = hz[state_im1j];

			ey[state] -= half * (hz_c - hz_im1);
		});

		// ------------------------------------------------------------------
		// 3) ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1])
		//    for i = 0..nx-1, j = 1..ny-1
		// ------------------------------------------------------------------
		// Restrict j to [1, ny-1]; dims: i (outer), j (inner)
		auto trav_ex_interior = trav_t.order(slice<'j'>(1, ny - 1));

		omp_trav_for_each_dim<'i'>(trav_ex_interior, [=](auto state) {
			// state: i in [0, nx-1], j in [1, ny-1], t fixed
			auto state_ijm1 = state - idx<'j'>(1);

			const num_t hz_c   = hz[state];
			const num_t hz_jm1 = hz[state_ijm1];

			ex[state] -= half * (hz_c - hz_jm1);
		});

