		// 4) hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j]
		//                                + ey[i+1][j] - ey[i][j])
		//    for i = 0..nx-2, j = 0..ny-2
		// ------------------------------------------------------------------
		// Slice i to [0, nx-2] and j to [0, ny-2]:
		//   slice<'i'>(0, nx - 1) -> i in [0, nx-2]
		//   slice<'j'>(0, ny - 1) -> j in [0, ny-2]
		auto trav_hz_interior =
			trav_t.order(slice<'i'>(0, nx - 1) ^ slice<'j'>(0, ny - 1));

		omp_trav_for_each_dim<'i'>(trav_hz_interior, [=](auto state) {
			// state: i in [0, nx-2], j in [0, ny-2], t fixed
			auto state_i_jp1 = state + idx<'j'>(1);
			auto state_ip1_j = state + idx<'i'>(1);

