//   ex[i][j]  -= 0.5 * (hz[i][j]   - hz[i][j-1])
//   hz[i][j]  -= 0.7 * (ex[i][j+1] - ex[i][j]
//                      + ey[i+1][j] - ey[i][j])
//
// The implementation below keeps exactly this update scheme while:
//   - keeping j as the innermost (contiguous) dimension
//   - using layout-preserving views (shift/slice) instead of per-iteration
//     index-state arithmetic (state +/- idx(...))
//   - avoiding redundant work such as recomputing neighbor states
// ---------------------------------------------------------------------------

[[gnu::flatten, gnu::noinline]]
