	// They are layout-preserving, so they do not allocate or copy data;
	// they only adjust how indices are interpreted.
	//
	//  - ey_ip1[i', j]  == ey[i'+1, j]  for i' in [0, nx-2]
	//  - hz_ip1[i', j]  == hz[i'+1, j]
	//  - ex_jp1[i, j']  == ex[i, j'+1]  for j' in [0, ny-2]
	//  - hz_jp1[i, j']  == hz[i, j'+1]
