		^ slice<'i'>(0, nx - 1); // trims 'i' to 0..nx-2, 'j' stays 0..ny-2
	auto ey_ip1_inner = ey_ip1
		^ slice<'j'>(0, ny - 1); // trims 'j' to 0..ny-2, 'i' stays 0..nx-2

#pragma scop
	// Outer time loop over t, expressed via a traverser on the fict array.
