		//
		// On the inner region i in [0, nx-2], j in [0, ny-2], we have:
		//   hz_inner[i, j]       == hz[i,   j]
		//   ex_jp1_inner[i, j]   == ex[i,   j+1]
		//   ey_ip1_inner[i, j]   == ey[i+1, j]
		//
		// So we can write:
		//   hz_inner[i, j] -= 0.7 * ((ex_jp1_inner[i, j] - ex[i, j]) +
		//                             (ey_ip1_inner[i, j] - ey[i, j]));
		//
		// This uses aligned sliced views instead of index-state arithmetic.
		// ----------------------------------------------------------------
		traverser(hz_inner, ex_jp1_inner, ey_ip1_inner).for_each([&](auto state) {
			// state: i in [0, nx-2], j in [0, ny-2]
			hz_inner[state] -= coeff_hz *
				((ex_jp1_inner[state] - ex[state]) +
				 (ey_ip1_inner[state] - ey[state]));
		});
	});
#pragma endscop
}

